-- Public Speaking and Communication final module. Run seed_psp_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'public-speaking';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Prepare and Deliver a Speech Portfolio$j$, $j${"prompt": "Prepare, deliver and evaluate a speech of three to five minutes, and write a portfolio report of at least 600 words. Ask a parent, guardian or teacher to approve your topic first, and choose an adult audience or a small trusted audience. Choose an appropriate topic that does not share private details about other people. Choose one type: (a) an informative speech on a topic you have researched, (b) a persuasive speech on a school or community issue, with a specific call to action, or (c) a special occasion speech, such as a tribute or a speech of introduction. If you cannot find a live audience, record yourself with an adult present. Proverbs 25:11 says, A word fitly spoken is like apples of gold in pictures of silver.\n\nPart 1: Topic and Purpose. State your topic, general purpose, specific purpose and central idea. Describe your audience and how you adapted to them.\nPart 2: Research and Sources. List at least three credible sources and tell how you checked each one with the CRAAP questions. Explain how you avoided plagiarism and gave oral credit.\nPart 3: Outline. Provide a full outline with an introduction (attention getter, topic, credibility and preview), a body with two to four main points and supporting material, transitions, and a conclusion.\nPart 4: Delivery Plan and Practice Log. Describe your voice, body language and visual aid plans. Record at least three practice sessions with the date, the time in minutes and one improvement made.\nPart 5: Delivery. Give your speech to your approved audience. Write the date, the length and the audience size.\nPart 6: Audience Feedback. Collect written feedback from at least two listeners, each giving two strengths and one suggestion. Summarize it.\nPart 7: Self Evaluation. Using your criteria for content, organization, delivery, language, audience connection and ethics, evaluate your own speech and name two goals for growth.\nPart 8: Faith and Calling. Explain how Psalm 19:14, Colossians 4:6 and Ephesians 4:29 guide the way you speak, and describe how you could use communication skills in a future calling.", "rubric": "100 points. Part 1, topic and purpose: 10 points. Part 2, research and sources: 10 points. Part 3, outline: 15 points. Part 4, delivery plan and practice log: 10 points. Part 5, delivery: 15 points. Part 6, audience feedback: 10 points. Part 7, self evaluation: 15 points. Part 8, faith and calling: 10 points. Grammar, conventions and respectful tone: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Prepare and Deliver a Speech Portfolio$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: Public Speaking and Communication$j$, $j${"questions": [{"q": "The person who has a message to share is the:", "options": ["Feedback", "Receiver", "Channel", "Sender"]}, {"q": "Anything that blocks or distorts a message is called:", "options": ["Channel", "Context", "Noise", "Feedback"]}, {"q": "Restating what a speaker said in your own words is:", "options": ["Memorizing", "Paraphrasing", "Plagiarizing", "Interrupting"]}, {"q": "Presenting someone else's words or ideas as your own is:", "options": ["Feedback", "Plagiarism", "Research", "Paraphrasing with credit"]}, {"q": "A statement of what the audience will understand, believe or do is the:", "options": ["Citation", "Transition", "Signpost", "Specific purpose"]}, {"q": "In the CRAAP checklist, the letter A that stands for accuracy asks whether the information:", "options": ["Is short", "Has pictures", "Is popular", "Is supported by evidence and can be confirmed"]}, {"q": "The three main parts of a speech are:", "options": ["Question, answer and applause", "Title, topic and theme", "Opening, middle and ending of the slides", "Introduction, body and conclusion"]}, {"q": "Conversation usually runs about how many words per minute?", "options": ["300 to 400", "120 to 150", "20 to 40", "600 to 700"]}, {"q": "A speech that is practiced and delivered from brief notes is:", "options": ["Extemporaneous", "Manuscript", "Memorized", "Impromptu"]}, {"q": "A good slide has:", "options": ["One main idea and few words", "Clashing colors", "No contrast", "Paragraphs in small type"]}, {"q": "Moving a listener to believe or do something is the purpose of a:", "options": ["Eulogy", "Introduction", "Persuasive speech", "Informative speech"]}, {"q": "In a STAR answer, the four parts are:", "options": ["Start, Talk, Answer and Rest", "Source, Time, Aim and Reason", "Situation, Task, Action and Result", "Speech, Topic, Audience and Reply"]}, {"q": "Attacking the person instead of the argument is the fallacy of:", "options": ["Slippery slope", "Red herring", "Ad hominem", "Straw man"]}, {"q": "A good rule for digital communication is to:", "options": ["Share passwords", "Post in anger", "Think before posting because posts can last", "Meet strangers alone"]}, {"q": "Colossians 4:6 says a believer's speech should be:", "options": ["Loud and proud", "Alway with grace, seasoned with salt", "Used to argue", "Silent in all places"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Public Speaking and Communication$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,1,1,3,3,3,1,0,0,2,2,2,2,1}'::int[], array[$j$The sender starts the communication process.$j$,$j$Noise can be external or internal.$j$,$j$Paraphrasing checks understanding.$j$,$j$It is dishonest and must be avoided.$j$,$j$It guides every choice in the speech.$j$,$j$Accurate information is supported and verifiable.$j$,$j$Most speeches follow this structure.$j$,$j$That range is clear and natural.$j$,$j$It is organized yet conversational.$j$,$j$Simple slides support the speaker.$j$,$j$Persuasion seeks a change in belief or action.$j$,$j$STAR organizes an experience story.$j$,$j$Ad hominem targets the person.$j$,$j$A digital footprint can last for years.$j$,$j$Gracious, wholesome speech serves others.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: Public Speaking and Communication$j$ on conflict (item_id) do nothing;
end
$seed$;
